void test_a_deleted_recording_leaves_the_background_queue(void)
{
    fxj_touch(&s_j, "REC01.WAV");
    TEST_ASSERT_TRUE(fxj_can_act(&s_j, true, s_now));       /* six effects to check */
    fxj_forget(&s_j, "REC01.WAV");                          /* the recording was deleted */
    TEST_ASSERT_FALSE(fxj_can_act(&s_j, true, s_now));      /* nothing left to make */
}

/* ======================================================================= */
/* 2. The waited job                                                        */
/* ======================================================================= */

/* A background job for (REC01, ECHO), stepped part of the way. */
static void start_background_job(void)
{
    add_recording("REC01.WAV", 1U);
    fxj_select(&s_j, FXS_EFFECT_ECHO);
    fxj_touch(&s_j, "REC01.WAV");
    for (uint32_t i = 0U; i < MAX_STEPS; i++)
    {
        if (s_j.job.active && s_j.job.pipe.src_done >= 4096U)
        {
            return;
        }
        (void)step(true);
    }
    TEST_FAIL_MESSAGE("the background job did not start");
}

void test_wanting_the_pair_being_made_adopts_it_and_keeps_its_progress(void)
{
    start_background_job();
    const uint32_t done_before = s_j.job.pipe.src_done;
    TEST_ASSERT_TRUE(fxj_is_running(&s_j, "REC01.WAV", FXS_EFFECT_ECHO));

    TEST_ASSERT_EQUAL(FXJ_ADOPTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
    TEST_ASSERT_EQUAL_UINT32(done_before, s_j.job.pipe.src_done);       /* nothing restarted */
    TEST_ASSERT_TRUE(fxj_want_percent(&s_j) > 0U);

    uint8_t last_percent = fxj_want_percent(&s_j);
    fxj_step_t r = FXJ_NOTHING;
    for (uint32_t i = 0U; i < MAX_STEPS && !is_end(r); i++)
    {
        r = step(false);
        if (!is_end(r))
        {
            TEST_ASSERT_TRUE(fxj_want_percent(&s_j) >= last_percent);  /* the percent never drops */
            last_percent = fxj_want_percent(&s_j);
        }
    }
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, r);
    TEST_ASSERT_EQUAL_UINT32(1U, s_first_flags);                         /* no second FX_REQ_FIRST */
}

void test_resume_of_the_pair_being_made_adopts_it_again(void)
{
    add_recording("REC01.WAV", 1U);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_REVERB, s_now));
    step_until_action(FXP_SEND, false);
    (void)step(false);

    /* PAUSE: the job carries on in the background ... */
    fxj_unwant(&s_j);
    TEST_ASSERT_TRUE(fxj_is_running(&s_j, "REC01.WAV", FXS_EFFECT_REVERB));
    (void)step(true);
    (void)step(true);

    /* ... and RESUME takes it back with its progress. */
    TEST_ASSERT_EQUAL(FXJ_ADOPTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_REVERB, s_now));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run(false));
    TEST_ASSERT_EQUAL_UINT32(1U, s_first_flags);
}

void test_wanting_another_pair_parks_the_running_job(void)
{
    start_background_job();
    /* The same recording with another effect is another pair. */
    TEST_ASSERT_FALSE(fxj_is_running(&s_j, "REC01.WAV", FXS_EFFECT_ROBOT));
    add_recording("REC02.WAV", 2U);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC02.WAV", FXS_EFFECT_ROBOT, s_now));
    TEST_ASSERT_FALSE(fxj_is_running(&s_j, "REC01.WAV", FXS_EFFECT_ECHO));
    TEST_ASSERT_TRUE(log_has("FX ECHO REC01.WAV parked at"));       /* its progress is in the park table */
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run(false));
    TEST_ASSERT_EQUAL(FXJ_VALID, check("REC02.WAV", FXS_EFFECT_ROBOT));

    /* The parked pair was not marked done: the background carries it on
     * (here rebuilt: REC02's chunks went through FxRenderTask meanwhile). */
    TEST_ASSERT_EQUAL(FXJ_STALE, check("REC01.WAV", FXS_EFFECT_ECHO));
    TEST_ASSERT_EQUAL(FXJ_NOTHING, run(true));
    TEST_ASSERT_EQUAL(FXJ_VALID, check("REC01.WAV", FXS_EFFECT_ECHO));
}

/* ======================================================================= */
/* 3. Requests out                                                          */
/* ======================================================================= */

void test_a_late_reply_of_an_aborted_job_is_dropped_unread(void)
{
    s_mode = RENDER_HOLDS;
    add_recording("REC01.WAV", 1U);
    (void)fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now);
    step_until_action(FXP_WAIT, false);
    TEST_ASSERT_TRUE(fxj_request_out(&s_j));

    fxj_abort(&s_j);
    TEST_ASSERT_TRUE(fxj_request_out(&s_j));         /* still recorded until its reply */
    expect_no_file_open();

    answer();                                        /* the late reply */
    TEST_ASSERT_FALSE(fxj_request_out(&s_j));
    TEST_ASSERT_FALSE(s_j.job.active);
    TEST_ASSERT_EQUAL_UINT32(0U, s_j.job.pipe.out_staged);   /* nothing copied */
}

void test_after_a_park_with_a_request_out_the_next_job_waits_for_the_late_reply(void)
{
    s_mode = RENDER_HOLDS;
    add_recording("REC01.WAV", 1U);
    add_recording("REC02.WAV", 2U);
    (void)fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now);
    step_until_action(FXP_WAIT, false);
    const uint16_t old_job = s_req.job;

    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC02.WAV", FXS_EFFECT_ECHO, s_now));
    step_until_action(FXP_SEND, false);
    TEST_ASSERT_FALSE(fxj_can_act(&s_j, false, s_now));      /* SEND, but a request is out */
    const uint32_t sends = s_sends;
    (void)fxj_step(&s_j, false, s_now);
    TEST_ASSERT_EQUAL_UINT32(sends, s_sends);

    answer();                                                /* the late reply comes */
    TEST_ASSERT_EQUAL_UINT32(0U, s_j.job.pipe.out_staged);   /* the old output was not taken */
    TEST_ASSERT_TRUE(fxj_can_act(&s_j, false, s_now));
    (void)fxj_step(&s_j, false, s_now);
    TEST_ASSERT_EQUAL_UINT32(sends + 1U, s_sends);
    TEST_ASSERT_TRUE(s_req.job != old_job);                  /* the new job has its own number */
}

void test_while_a_request_is_out_the_engine_only_acts_on_reads_and_writes(void)
{
    s_mode = RENDER_HOLDS;                                   /* FxRenderTask never answers */
    add_recording("REC01.WAV", 1U);
    (void)fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now);
    uint32_t steps = 0U;
    while (fxj_can_act(&s_j, false, s_now) && steps < MAX_STEPS)
    {
        if (fxj_request_out(&s_j) && s_j.job.phase == J_RUN)
        {
            const fxp_action_t a = fxp_next(&s_j.job.pipe);
            TEST_ASSERT_TRUE(a == FXP_READ || a == FXP_WRITE);
        }
        (void)fxj_step(&s_j, false, s_now);
        s_now++;
        steps++;
    }
    /* It stops acting (Jack then blocks 2 ticks per pass on the reply queue). */
    TEST_ASSERT_TRUE(steps < MAX_STEPS);
    TEST_ASSERT_TRUE(fxj_request_out(&s_j));
    TEST_ASSERT_EQUAL(FXP_WAIT, fxp_next(&s_j.job.pipe));
}

void test_can_act_means_the_next_step_makes_progress(void)
{
    /* Whole jobs with checks, an abort with a request out, a late reply and
     * a failure: run() asserts the rule on every step. */
    add_recording("REC01.WAV", 1U);
    add_recording("REC02.WAV", 2U);
    fxj_touch(&s_j, "REC01.WAV");
    fxj_touch(&s_j, "REC02.WAV");
    for (uint32_t i = 0U; i < 300U; i++)
    {
        (void)step(true);
    }
    s_mode = RENDER_HOLDS;
    step_until_action(FXP_WAIT, true);
    fxj_abort(&s_j);
    TEST_ASSERT_EQUAL(FXJ_NOTHING, run(true));               /* checks and phases, until SEND is blocked */
    answer();
    s_mode = RENDER_ANSWERS;
    StoragePortFake_CardFailOp(STORAGE_FAKE_OP_FX_WRITE, 3U, STORAGE_WRITE_FAIL);
    TEST_ASSERT_EQUAL(FXJ_NOTHING, run(true));               /* the failure halts the background */
    TEST_ASSERT_TRUE(s_j.bg_halted);
}

void test_a_refused_send_moves_nothing_and_after_30_s_the_waited_job_gives_up(void)
{
    s_mode = RENDER_REFUSES;
    add_recording("REC01.WAV", 1U);
    (void)fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now);
    step_until_action(FXP_SEND, false);

    const uint32_t before = fxj_progress(&s_j);
    TEST_ASSERT_TRUE(fxj_can_act(&s_j, false, s_now));
    TEST_ASSERT_EQUAL(FXJ_NOTHING, fxj_step(&s_j, false, s_now));
    TEST_ASSERT_EQUAL_UINT32(before, fxj_progress(&s_j));      /* the loop guard then waits 2 ms */
    (void)fxj_step(&s_j, false, s_now + FXJ_GUARD_WAIT_MS);    /* and it tries again */
    TEST_ASSERT_EQUAL_UINT32(2U, s_refusals);
    TEST_ASSERT_FALSE(fxj_stalled(&s_j, s_now + FXJ_STALL_MS));

    s_now += FXJ_STALL_MS + 1U;
    TEST_ASSERT_TRUE(fxj_stalled(&s_j, s_now));
    TEST_ASSERT_EQUAL(FXJ_WANT_GAVE_UP, fxj_step(&s_j, false, s_now));
    expect_no_file_open();
}

void test_idle_wait_is_0_when_work_can_act_2_after_an_idle_pass_and_100_otherwise(void)
{
    TEST_ASSERT_EQUAL_UINT32(0U, fxj_idle_wait_ms(true, false));
    TEST_ASSERT_EQUAL_UINT32(FXJ_GUARD_WAIT_MS, fxj_idle_wait_ms(true, true));
    TEST_ASSERT_EQUAL_UINT32(FXJ_IDLE_WAIT_MS, fxj_idle_wait_ms(false, false));
    TEST_ASSERT_EQUAL_UINT32(FXJ_IDLE_WAIT_MS, fxj_idle_wait_ms(false, true));
}

