    TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND, fxj_fingerprint(&s_j, "GONE.WAV", &src));
    StoragePortFake_CardPull(true);
    TEST_ASSERT_EQUAL(STORAGE_READ_FAIL, fxj_fingerprint(&s_j, "JUNK.WAV", &src));
