void test_fingerprint_and_check_close_what_they_open(void)
{
    add_recording("REC01.WAV", 1U);
    make_file("REC01.WAV", FXS_EFFECT_ECHO);
    fx_src_t src;
    TEST_ASSERT_EQUAL(STORAGE_OK, fxj_fingerprint(&s_j, "REC01.WAV", &src));
    expect_no_file_open();
    TEST_ASSERT_EQUAL(FXJ_STALE, fxj_check(&s_j, "REC01.WAV", FXS_EFFECT_ROBOT, &src, true, NULL));
    expect_no_file_open();
    TEST_ASSERT_EQUAL(FXJ_VALID, fxj_check(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, &src, false, NULL));
    expect_no_file_open();

    /* Kept open only when asked, and then at its first sample. */
    wav_header_t hdr;
    TEST_ASSERT_EQUAL(FXJ_VALID, fxj_check(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, &src, true, &hdr));
    TEST_ASSERT_TRUE(StoragePortFake_CardReadFileOpen());
    TEST_ASSERT_EQUAL_UINT32(1U, StoragePortFake_CardSlotsInUse());
    TEST_ASSERT_EQUAL_UINT32(FXS_HEADER_BYTES, hdr.data_offset);
    TEST_ASSERT_EQUAL_UINT32(2U * ONE_SECOND_OUT, hdr.data_size);
    uint8_t first[2];
    size_t got = 0U;
    TEST_ASSERT_EQUAL(STORAGE_OK, Storage_ReadChunk(first, sizeof(first), &got));
    TEST_ASSERT_EQUAL_UINT8(StoragePortFake_CardFileData("FX/ECHO/REC01.WAV")[FXS_HEADER_BYTES], first[0]);
}

