void test_check_gives_valid_stale_or_io_error(void)
{
    add_recording("REC01.WAV", 1U);
    make_file("REC01.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_EQUAL(FXJ_VALID, check("REC01.WAV", FXS_EFFECT_ECHO));

    fx_src_t src;
    TEST_ASSERT_EQUAL(STORAGE_OK, fxj_fingerprint(&s_j, "REC01.WAV", &src));
    StoragePortFake_CardPull(true);
    TEST_ASSERT_EQUAL(FXJ_IO_ERROR, fxj_check(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, &src, false, NULL));
    StoragePortFake_CardPull(false);

    TEST_ASSERT_EQUAL(STORAGE_OK, Storage_Unlink("FX/ECHO/REC01.WAV"));
    TEST_ASSERT_EQUAL(FXJ_STALE, check("REC01.WAV", FXS_EFFECT_ECHO));
}

void test_a_recording_made_again_makes_its_old_effect_files_stale(void)
{
    add_recording("REC01.WAV", 1U);
    make_file("REC01.WAV", FXS_EFFECT_ECHO);
    add_recording("REC01.WAV", 9U);                  /* the same name and size, other sound */
    TEST_ASSERT_EQUAL(FXJ_STALE, check("REC01.WAV", FXS_EFFECT_ECHO));
}

/* Replace FX/ECHO/REC01.WAV by a copy of its first keep bytes, with the
 * "data" size in its header set to declared. */
static void rewrite_effect_file(uint32_t keep, uint32_t declared)
{
    const uint8_t *made = StoragePortFake_CardFileData("FX/ECHO/REC01.WAV");
    uint8_t *copy = (uint8_t *)malloc(keep);
    TEST_ASSERT_NOT_NULL(copy);
    memcpy(copy, made, keep);
    copy[64] = (uint8_t)(declared & 0xFFU);
    copy[65] = (uint8_t)((declared >> 8) & 0xFFU);
    copy[66] = (uint8_t)((declared >> 16) & 0xFFU);
    copy[67] = (uint8_t)(declared >> 24);
    TEST_ASSERT_TRUE(StoragePortFake_CardAddFile("FX/ECHO/REC01.WAV", copy, keep));
    free(copy);
}

void test_a_truncated_effect_file_is_stale(void)
{
    add_recording("REC01.WAV", 1U);
    make_file("REC01.WAV", FXS_EFFECT_ECHO);
    rewrite_effect_file(FXS_HEADER_BYTES + 50000U, 2U * ONE_SECOND_OUT);   /* cut short on a PC */
    TEST_ASSERT_EQUAL(FXJ_STALE, check("REC01.WAV", FXS_EFFECT_ECHO));
}

void test_an_effect_file_whose_header_says_data_0_is_stale(void)
{
    /* wav_parse_header would read "data 0" as "to the end of the file": the
     * check compares the size the header DECLARES with the file. */
    add_recording("REC01.WAV", 1U);
    make_file("REC01.WAV", FXS_EFFECT_ECHO);
    rewrite_effect_file(FXS_HEADER_BYTES + 2U * ONE_SECOND_OUT, 0U);
    TEST_ASSERT_EQUAL(FXJ_STALE, check("REC01.WAV", FXS_EFFECT_ECHO));
}

void test_a_tmp_beside_a_valid_wav_makes_it_stale(void)
{
    /* A power loss inside the rename leaves both names on one cluster chain. */
    add_recording("REC01.WAV", 1U);
    make_file("REC01.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_TRUE(StoragePortFake_CardAddFile("FX/ECHO/REC01.TMP", NULL, 0U));
    TEST_ASSERT_EQUAL(FXJ_STALE, check("REC01.WAV", FXS_EFFECT_ECHO));
}

