/* Where an abort is tried: each phase, and J_RUN in three situations. */
typedef enum {
    AT_PHASE = 0,             /* the job has reached the phase */
    AT_INPUT_STAGED,          /* J_RUN with source samples read but not all sent */
    AT_REQUEST_OUT,           /* J_RUN with a chunk out */
    AT_OUTPUT_STAGED,         /* J_RUN with effect samples not yet written */
    AT_HALF_DONE              /* J_RUN with the output of half the source back (group 9) */
} abort_point_t;

static bool abort_point_reached(fxj_phase_t phase, abort_point_t point)
{
    const fxj_job_t *job = &s_j.job;
    if (!job->active || job->phase != phase)
    {
        return false;
    }
    if (point == AT_INPUT_STAGED)
    {
        return job->pipe.stage_pos < job->pipe.stage_len;
    }
    if (point == AT_REQUEST_OUT)
    {
        return job->pipe.inflight;
    }
    if (point == AT_OUTPUT_STAGED)
    {
        return job->pipe.out_staged > 0U;
    }
    if (point == AT_HALF_DONE)
    {
        return (job->pipe.src_done * 2U) >= job->pipe.src_total;
    }
    return true;
}

static void abort_at(fxj_phase_t phase, abort_point_t point)
{
    fresh_engine();
    s_mode = (point == AT_REQUEST_OUT) ? RENDER_HOLDS : RENDER_ANSWERS;
    add_recording("REC01.WAV", 1U);
    (void)fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now);
    for (uint32_t i = 0U; i < MAX_STEPS && !abort_point_reached(phase, point); i++)
    {
        (void)step(false);
    }
    TEST_ASSERT_TRUE(abort_point_reached(phase, point));
    fxj_abort(&s_j);
    expect_no_file_open();
    TEST_ASSERT_FALSE(s_j.job.active);
}

void test_an_abort_in_every_phase_frees_both_lock_slots(void)
{
    static const fxj_phase_t phases[] = {
        J_MKDIR_ROOT, J_MKDIR_EFFECT, J_CLEAN, J_OPEN_SRC, J_SPACE, J_CREATE, J_RUN, J_CLOSE, J_RENAME
    };
    for (size_t i = 0U; i < (sizeof(phases) / sizeof(phases[0])); i++)
    {
        abort_at(phases[i], AT_PHASE);
    }
    abort_at(J_RUN, AT_INPUT_STAGED);
    abort_at(J_RUN, AT_REQUEST_OUT);
    abort_at(J_RUN, AT_OUTPUT_STAGED);
}

