/* 9. Park and resume (TEAM CODE, written by Brendon, 30 Oct 2026)          */
/* ======================================================================= */

#define SOURCE_48K_BYTES  96000U            /* 1 s at 48 kHz: 48 000 samples (the last chunk 384) */
#define REF_FILES         2U                /* reference files a test can keep */
#define PARTLY_SAMPLES    4096U             /* "run partly": this much source done */

static uint8_t *s_ref[REF_FILES];           /* the files jobs make in one go (malloc'd) */
static uint32_t s_ref_size[REF_FILES];
static char     s_case[64];                 /* which case a loop is on, for a failure message */

static void free_references(void)
{
    for (uint32_t k = 0U; k < REF_FILES; k++)
    {
        free(s_ref[k]);
        s_ref[k] = NULL;
        s_ref_size[k] = 0U;
    }
}

/* A recording of `seconds` at rate (seed: another seed = another recording). */
static void add_source_s(const char *name, uint32_t rate, uint8_t seed, uint32_t seconds)
{
    add_wav(name, rate, 1U, 16U, seconds * ((rate == RATE_48K) ? SOURCE_48K_BYTES : ONE_SECOND_BYTES), seed);
}

/* A 1 s recording at rate. */
static void add_source(const char *name, uint32_t rate, uint8_t seed)
{
    add_source_s(name, rate, seed, 1U);
}

static void fx_path(uint8_t effect, const char *name, bool tmp, char *out)
{
    TEST_ASSERT_TRUE(fx_file_path(effect, name, tmp, out, FXS_PATH_LEN));
}

/* A fresh engine and card, the fake effect with its memory. */
static void fresh_with_memory(void)
{
    fresh_engine();
    s_render_memory = true;
}

/* Keep the file a job makes in one go from a recording of `seconds` as
 * reference k: a parked and resumed job must make exactly these bytes.
 * Leaves a fresh engine and card. */
static void make_reference_s(uint32_t k, const char *name, uint8_t effect, uint32_t rate, uint8_t seed,
                             uint32_t seconds)
{
    fresh_with_memory();
    add_source_s(name, rate, seed, seconds);
    make_file(name, effect);
    char path[FXS_PATH_LEN];
    fx_path(effect, name, false, path);
    free(s_ref[k]);
    s_ref_size[k] = StoragePortFake_CardFileSize(path);
    s_ref[k] = (uint8_t *)malloc(s_ref_size[k]);
    TEST_ASSERT_NOT_NULL(s_ref[k]);
    memcpy(s_ref[k], StoragePortFake_CardFileData(path), s_ref_size[k]);
    fresh_with_memory();
}

/* The same for a 1 s recording. */
static void make_reference(uint32_t k, const char *name, uint8_t effect, uint32_t rate, uint8_t seed)
{
    make_reference_s(k, name, effect, rate, seed, 1U);
}

/* FX/<effect>/<name>.WAV is byte for byte reference k. */
static void expect_reference(uint32_t k, const char *name, uint8_t effect)
{
    char path[FXS_PATH_LEN];
    fx_path(effect, name, false, path);
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(s_ref_size[k], StoragePortFake_CardFileSize(path), s_case);
    TEST_ASSERT_EQUAL_MEMORY_MESSAGE(s_ref[k], StoragePortFake_CardFileData(path), s_ref_size[k], s_case);
}

/* One step; FatFs's two lock slots are never short (a third open would
 * fail the job with NO_SLOT). */
static fxj_step_t step_in_budget(bool background)
{
    const fxj_step_t r = step(background);
    TEST_ASSERT_TRUE(StoragePortFake_CardSlotsInUse() <= STORAGE_FAKE_LOCK_SLOTS);
    TEST_ASSERT_TRUE_MESSAGE(fxj_last_fail(&s_j) != FXJ_FAIL_NO_SLOT, s_case);
    return r;
}

/* Run the waited job to its end. */
static fxj_step_t run_waited(void)
{
    for (uint32_t i = 0U; i < MAX_STEPS; i++)
    {
        const fxj_step_t r = step_in_budget(false);
        if (is_end(r))
        {
            return r;
        }
    }
    TEST_FAIL_MESSAGE("the waited job never ended");
    return FXJ_NOTHING;
}

/* What jack_fx_park does: FxRenderTask's reply comes during the wait
 * (answer), then the park. Afterwards no file is open and no lock slot is
 * used. Returns the waited percentage at the moment of the park. */
static uint8_t park_now(void)
{
    answer();
    const uint8_t pct = fxj_want_percent(&s_j);
    fxj_park(&s_j);
    TEST_ASSERT_FALSE(s_j.job.active);
    expect_no_file_open();
    return pct;
}

/* Want (name, effect) and step it until source_done source samples are back. */
static void want_and_run_partly(const char *name, uint8_t effect, uint32_t source_done)
{
    answer();                                       /* the glue's wait before a want parks the slot job */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, name, effect, s_now));
    for (uint32_t i = 0U; i < MAX_STEPS; i++)
    {
        if (s_j.job.active && s_j.job.phase == J_RUN && s_j.job.pipe.src_done >= source_done)
        {
            return;
        }
        (void)step_in_budget(false);
    }
    TEST_FAIL_MESSAGE("the job never got that far");
}

static uint32_t rows_used(void)
{
    uint32_t used = 0U;
    for (uint32_t i = 0U; i < FXJ_PARK_ROWS; i++)
    {
        if (s_j.parked[i].used)
        {
            used++;
        }
    }
    return used;
}

static const fxj_parked_t *row_of(const char *name, uint8_t effect)
{
    for (uint32_t i = 0U; i < FXJ_PARK_ROWS; i++)
    {
        const fxj_parked_t *row = &s_j.parked[i];
        if (row->used && row->effect == effect && strcmp(row->name, name) == 0)
        {
            return row;
        }
    }
    return NULL;
}

/* The park points of the identity test: early phases (nothing worth
 * keeping), J_RUN in several situations, and J_CLOSE / J_RENAME (a complete
 * but unrenamed .TMP must never be lost). */
typedef struct {
    fxj_phase_t   phase;
    abort_point_t point;
} park_point_t;

static const park_point_t k_park_points[] = {
    { J_MKDIR_ROOT, AT_PHASE }, { J_CLEAN, AT_PHASE }, { J_OPEN_SRC, AT_PHASE }, { J_SPACE, AT_PHASE },
    { J_CREATE, AT_PHASE }, { J_RUN, AT_PHASE }, { J_RUN, AT_INPUT_STAGED }, { J_RUN, AT_REQUEST_OUT },
    { J_RUN, AT_OUTPUT_STAGED }, { J_RUN, AT_HALF_DONE }, { J_CLOSE, AT_PHASE }, { J_RENAME, AT_PHASE },
};

/* Park the waited job of (REC01, effect) at a point, want it again with
 * nothing else in between, and check its file against reference 0. */
static void park_and_resume_at(uint8_t effect, uint32_t rate, const park_point_t *at)
{
    fresh_with_memory();
    add_source("REC01.WAV", rate, 1U);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", effect, s_now));
    for (uint32_t i = 0U; i < MAX_STEPS && !abort_point_reached(at->phase, at->point); i++)
    {
        (void)step_in_budget(false);
    }
    TEST_ASSERT_TRUE_MESSAGE(abort_point_reached(at->phase, at->point), s_case);
    answer();                                        /* the reply comes during the park's wait */
    const bool kept = (at->phase >= J_RUN) && (s_j.job.pipe.src_done > 0U);   /* something rendered */
    const uint8_t pct = park_now();
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(kept ? 1U : 0U, rows_used(), s_case);

    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", effect, s_now));
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(pct, fxj_want_percent(&s_j), s_case);     /* shown at once */
    TEST_ASSERT_EQUAL_MESSAGE(FXJ_WANT_DONE, run_waited(), s_case);
    expect_reference(0U, "REC01.WAV", effect);
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(1U, s_first_flags, s_case);   /* exact: one FIRST for the whole file */
    TEST_ASSERT_FALSE_MESSAGE(log_has("made again"), s_case);
    TEST_ASSERT_EQUAL_MESSAGE(kept, log_has("resumed at"), s_case);
    TEST_ASSERT_EQUAL_MESSAGE(FXJ_FAIL_NONE, fxj_last_fail(&s_j), s_case);
}

void test_a_parked_and_resumed_file_is_byte_identical_for_every_effect_rate_and_point(void)
{
    static const uint32_t rates[] = { RATE_32K, RATE_48K };
    for (uint8_t effect = FXS_EFFECT_AUTOTUNE; effect <= FXS_EFFECT_COUNT; effect++)
    {
        for (size_t r = 0U; r < (sizeof(rates) / sizeof(rates[0])); r++)
        {
            make_reference(0U, "REC01.WAV", effect, rates[r], 1U);
            for (size_t i = 0U; i < (sizeof(k_park_points) / sizeof(k_park_points[0])); i++)
            {
                (void)snprintf(s_case, sizeof(s_case), "effect %u, %lu Hz, phase %d, point %d",
                               (unsigned)effect, (unsigned long)rates[r],
                               (int)k_park_points[i].phase, (int)k_park_points[i].point);
                park_and_resume_at(effect, rates[r], &k_park_points[i]);
            }
        }
    }
}

void test_a_resume_after_another_job_ran_is_rebuilt_and_says_so(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, 16384U);
    answer();
    const uint8_t pct = fxj_want_percent(&s_j);
    TEST_ASSERT_TRUE(pct > 0U);

    /* Another job runs whole chunks through FxRenderTask meanwhile. */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC02.WAV", FXS_EFFECT_ROBOT, s_now));
    TEST_ASSERT_NOT_NULL(row_of("REC01.WAV", FXS_EFFECT_ECHO));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());

    /* Wanted again: its parked percentage at once, then (Part B) it is
     * rebuilt, logged, and the file is still exactly right. Echo's pre-roll
     * is 4 s, more than this 1 s recording, so the rebuild runs the effect
     * from sample 0 (no RESTORE) and throws that output away; the .TMP is
     * kept. It keeps the new job number: FxRenderTask's state is not its
     * old number's. */
    const uint16_t parked_id = row_of("REC01.WAV", FXS_EFFECT_ECHO)->resume.id;
    const uint32_t unlinks = StoragePortFake_GetOpCallCount(STORAGE_FAKE_OP_UNLINK);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
    TEST_ASSERT_EQUAL_UINT8(pct, fxj_want_percent(&s_j));
    step_until_phase(J_SPACE);
    TEST_ASSERT_TRUE(s_j.job.id != parked_id);
    TEST_ASSERT_FALSE(s_j.job.pipe.first_sent);                 /* its first chunk will carry FIRST */
    TEST_ASSERT_EQUAL_UINT32(0U, s_j.job.pipe.src_read);        /* ... at sample 0 */
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_TRUE(log_has("FX ECHO REC01.WAV rebuilt, pre-roll"));
    TEST_ASSERT_TRUE(log_has("another job ran since"));
    TEST_ASSERT_FALSE(log_has("made again"));
    TEST_ASSERT_EQUAL_UINT32(unlinks + 1U, StoragePortFake_GetOpCallCount(STORAGE_FAKE_OP_UNLINK));   /* only the old .WAV */
    TEST_ASSERT_EQUAL_UINT32(3U, s_first_flags);               /* REC01, REC02, REC01's rebuild */
    TEST_ASSERT_EQUAL_UINT32(0U, s_restores);
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO);
}

void test_a_job_parked_with_nothing_left_to_render_never_starts_again(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
    step_until_phase(J_RENAME);
    TEST_ASSERT_EQUAL_UINT8(100U, park_now());
    make_file("REC02.WAV", FXS_EFFECT_ROBOT);                   /* another job in between */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
    TEST_ASSERT_EQUAL_UINT8(100U, fxj_want_percent(&s_j));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_FALSE(log_has("made again"));
    TEST_ASSERT_EQUAL_UINT32(2U, s_first_flags);
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO);
}

void test_a_park_takes_an_empty_row_and_a_full_table_drops_the_oldest_with_its_tmp(void)
{
    static const char *const names[] = {
        "REC01.WAV", "REC02.WAV", "REC03.WAV", "REC04.WAV", "REC05.WAV", "REC06.WAV", "REC07.WAV"
    };
    for (uint32_t i = 0U; i < 7U; i++)
    {
        add_recording(names[i], (uint8_t)(i + 1U));
    }
    for (uint32_t i = 0U; i < 7U; i++)
    {
        want_and_run_partly(names[i], FXS_EFFECT_ECHO, PARTLY_SAMPLES);
        TEST_ASSERT_EQUAL_UINT32((i < FXJ_PARK_ROWS) ? i : FXJ_PARK_ROWS, rows_used());   /* an empty row each */
        TEST_ASSERT_FALSE(log_has("dropped"));
    }
    (void)park_now();                                           /* the 7th park: the table is full */
    TEST_ASSERT_EQUAL_UINT32(FXJ_PARK_ROWS, rows_used());
    TEST_ASSERT_NULL(row_of("REC01.WAV", FXS_EFFECT_ECHO));     /* the oldest went ... */
    TEST_ASSERT_TRUE(log_has("FX ECHO REC01.WAV: its parked progress is dropped"));
    TEST_ASSERT_FALSE(StoragePortFake_CardExists("FX/ECHO/REC01.TMP"));   /* ... with its .TMP, at once */
    for (uint32_t i = 1U; i < 7U; i++)
    {
        TEST_ASSERT_NOT_NULL(row_of(names[i], FXS_EFFECT_ECHO));
        char tmp[FXS_PATH_LEN];
        fx_path(FXS_EFFECT_ECHO, names[i], true, tmp);
        TEST_ASSERT_TRUE(StoragePortFake_CardExists(tmp));
    }
}

void test_a_park_replaces_its_own_row(void)
{
    add_recording("REC01.WAV", 1U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, PARTLY_SAMPLES);
    (void)park_now();
    const fxj_parked_t first = *row_of("REC01.WAV", FXS_EFFECT_ECHO);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, 4U * PARTLY_SAMPLES);   /* takes the row ... */
    TEST_ASSERT_EQUAL_UINT32(0U, rows_used());
    /* ... so a pair never has a row while it runs. If a stale one were
     * there all the same, its park must replace it, not add a second. */
    s_j.parked[3] = first;
    (void)park_now();
    TEST_ASSERT_EQUAL_UINT32(1U, rows_used());
    TEST_ASSERT_TRUE(row_of("REC01.WAV", FXS_EFFECT_ECHO)->resume.src_at > first.resume.src_at);
}

/* REC01..REC06 (Echo) parked partly made, in that order, so the table is
 * full and REC01's row is the oldest; REC07 (Echo) runs in the slot.
 * Returns the percentage REC01 shows when it is wanted again. */
static uint8_t fill_the_table_with_rec07_running(void)
{
    static const char *const names[] = {
        "REC01.WAV", "REC02.WAV", "REC03.WAV", "REC04.WAV", "REC05.WAV", "REC06.WAV", "REC07.WAV"
    };
    for (uint32_t i = 0U; i < 7U; i++)
    {
        add_recording(names[i], (uint8_t)(i + 1U));
        want_and_run_partly(names[i], FXS_EFFECT_ECHO, PARTLY_SAMPLES);
    }
    TEST_ASSERT_EQUAL_UINT32(FXJ_PARK_ROWS, rows_used());
    answer();                                       /* the glue's wait before any park */
    const uint8_t pct = row_of("REC01.WAV", FXS_EFFECT_ECHO)->resume.pct;
    TEST_ASSERT_TRUE(pct > 0U);
    return (uint8_t)(pct - (pct % FXJ_PCT_STEP_WAIT));
}

/* REC01 was just wanted with the table full: nothing was dropped (REC07's
 * park took the place REC01's row left), REC01 shows its saved percentage
 * at once, and its file is made. */
static void expect_rec01_wanted_and_nothing_dropped(uint8_t pct)
{
    TEST_ASSERT_FALSE(log_has("dropped"));
    TEST_ASSERT_EQUAL_UINT32(FXJ_PARK_ROWS, rows_used());
    TEST_ASSERT_NULL(row_of("REC01.WAV", FXS_EFFECT_ECHO));     /* it runs: its row is out */
    TEST_ASSERT_NOT_NULL(row_of("REC07.WAV", FXS_EFFECT_ECHO));
    TEST_ASSERT_TRUE(s_j.job.resume.valid);
    TEST_ASSERT_EQUAL_UINT8(pct, fxj_want_percent(&s_j));
    TEST_ASSERT_TRUE(StoragePortFake_CardExists("FX/ECHO/REC01.TMP"));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_EQUAL(FXJ_VALID, check("REC01.WAV", FXS_EFFECT_ECHO));
}

/* fxj_want alone (the engine's order): the wanted row comes out first. */
void test_wanting_a_parked_pair_takes_its_row_before_the_park_so_nothing_is_dropped(void)
{
    const uint8_t pct = fill_the_table_with_rec07_running();
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));   /* parks REC07 */
    expect_rec01_wanted_and_nothing_dropped(pct);
}

/* Jack's glue order: PLAY parks the slot job FIRST (play_read_source, before
 * it knows whether the effect must be made), checks the effect file, and
 * only then wants the pair (play_prepare). fxj_park_for sets the wanted row
 * aside before the park, so the result is the same as above. */
void test_parking_for_a_parked_pair_then_wanting_it_drops_nothing(void)
{
    const uint8_t pct = fill_the_table_with_rec07_running();
    fxj_park_for(&s_j, "REC01.WAV", FXS_EFFECT_ECHO);           /* play_read_source */
    expect_no_file_open();
    TEST_ASSERT_FALSE(log_has("dropped"));                      /* REC07's park took REC01's place */
    TEST_ASSERT_TRUE(s_j.held.used);
    TEST_ASSERT_EQUAL(FXJ_STALE, check("REC01.WAV", FXS_EFFECT_ECHO));      /* play_check: not made */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));   /* play_prepare */
    TEST_ASSERT_FALSE(s_j.held.used);
    expect_rec01_wanted_and_nothing_dropped(pct);
}

/* No want follows the park (the effect file was made after all, or the
 * play failed): the next step puts the held row back, as parked now, so
 * the oldest OTHER row makes room. A row held for one pair also goes back
 * when another pair is wanted. */
void test_a_held_row_goes_back_into_the_table_when_no_want_follows(void)
{
    (void)fill_the_table_with_rec07_running();
    fxj_park_for(&s_j, "REC01.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_EQUAL_UINT32(FXJ_PARK_ROWS, rows_used());       /* REC02..REC07, nothing dropped yet */
    (void)fxj_step(&s_j, false, s_now);
    TEST_ASSERT_FALSE(s_j.held.used);
    TEST_ASSERT_EQUAL_UINT32(FXJ_PARK_ROWS, rows_used());
    TEST_ASSERT_NOT_NULL(row_of("REC01.WAV", FXS_EFFECT_ECHO));
    TEST_ASSERT_NULL(row_of("REC02.WAV", FXS_EFFECT_ECHO));
    TEST_ASSERT_TRUE(log_has("FX ECHO REC02.WAV: its parked progress is dropped"));
    TEST_ASSERT_FALSE(StoragePortFake_CardExists("FX/ECHO/REC02.TMP"));

    fxj_park_for(&s_j, "REC03.WAV", FXS_EFFECT_ECHO);           /* held ... */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC04.WAV", FXS_EFFECT_ECHO, s_now));
    TEST_ASSERT_FALSE(s_j.held.used);                           /* ... and back */
    TEST_ASSERT_NOT_NULL(row_of("REC03.WAV", FXS_EFFECT_ECHO));
    TEST_ASSERT_NULL(row_of("REC04.WAV", FXS_EFFECT_ECHO));     /* it runs */
    TEST_ASSERT_TRUE(s_j.job.resume.valid);
}

/* DELETE (or REC99 over the name) and an unmount drop a held row too. */
void test_forget_and_unmount_drop_a_held_row_too(void)
{
    add_recording("REC01.WAV", 1U);
    add_recording("REC02.WAV", 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, PARTLY_SAMPLES);
    want_and_run_partly("REC02.WAV", FXS_EFFECT_ECHO, PARTLY_SAMPLES);
    answer();
    fxj_park_for(&s_j, "REC01.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_TRUE(s_j.held.used);
    fxj_forget(&s_j, "REC01.WAV");
    TEST_ASSERT_FALSE(s_j.held.used);
    (void)fxj_step(&s_j, false, s_now);
    TEST_ASSERT_NULL(row_of("REC01.WAV", FXS_EFFECT_ECHO));     /* nothing comes back */
    TEST_ASSERT_NOT_NULL(row_of("REC02.WAV", FXS_EFFECT_ECHO));

    fxj_park_for(&s_j, "REC02.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_TRUE(s_j.held.used);
    fxj_on_unmount(&s_j);
    TEST_ASSERT_FALSE(s_j.held.used);
    TEST_ASSERT_EQUAL_UINT32(0U, rows_used());
}

/* A -> B -> A -> B with two recordings and the same effect. Both rows are
 * kept and each pair shows its saved percentage at once. Neither carries on
 * exactly: B sent chunks after A's park (and A after B's), so FxRenderTask
 * holds neither's state. So each is rebuilt (logged), and each file is still
 * exactly the one made in one go. */
void test_a_swap_a_b_a_keeps_both_rows_and_rebuilds_each(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO, RATE_32K, 1U);
    make_reference(1U, "REC02.WAV", FXS_EFFECT_ECHO, RATE_32K, 2U);
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, 13312U);   /* about 40 % */
    answer();
    const uint8_t pct_a = fxj_want_percent(&s_j);
    want_and_run_partly("REC02.WAV", FXS_EFFECT_ECHO, 9728U);    /* about 30 % */
    answer();
    const uint8_t pct_b = fxj_want_percent(&s_j);
    TEST_ASSERT_TRUE(pct_a >= 40U && pct_b >= 30U);
    TEST_ASSERT_EQUAL_UINT32(2U, s_first_flags);

    /* Back to A: its percentage at once, and B's row is kept. */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
    TEST_ASSERT_EQUAL_UINT8(pct_a, fxj_want_percent(&s_j));
    const fxj_parked_t *row_b = row_of("REC02.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_NOT_NULL(row_b);
    TEST_ASSERT_EQUAL_UINT8(pct_b, row_b->resume.pct - (row_b->resume.pct % FXJ_PCT_STEP_WAIT));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_TRUE(log_has("FX ECHO REC01.WAV rebuilt, pre-roll"));
    TEST_ASSERT_TRUE(log_has("another job ran since"));
    TEST_ASSERT_TRUE(log_has("FX ECHO REC01.WAV resumed at"));
    TEST_ASSERT_FALSE(log_has("made again"));
    TEST_ASSERT_EQUAL_UINT32(3U, s_first_flags);                /* A's rebuild starts with a FIRST */
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO);

    /* And B again: its percentage at once, then rebuilt too. */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC02.WAV", FXS_EFFECT_ECHO, s_now));
    TEST_ASSERT_EQUAL_UINT8(pct_b, fxj_want_percent(&s_j));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_TRUE(log_has("FX ECHO REC02.WAV rebuilt, pre-roll"));
    TEST_ASSERT_FALSE(log_has("made again"));
    TEST_ASSERT_EQUAL_UINT32(4U, s_first_flags);
    expect_reference(1U, "REC02.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_EQUAL_UINT32(0U, rows_used());
}

void test_switching_back_before_the_other_job_sends_a_chunk_carries_on_exactly(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_AUTOTUNE, 16384U);
    answer();
    const uint8_t pct = fxj_want_percent(&s_j);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC02.WAV", FXS_EFFECT_ECHO, s_now));
    step_until_phase(J_CREATE);                                 /* B has sent nothing yet */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_AUTOTUNE, s_now));
    TEST_ASSERT_EQUAL_UINT8(pct, fxj_want_percent(&s_j));
    TEST_ASSERT_EQUAL_UINT32(0U, rows_used());                  /* B had nothing worth keeping */
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_FALSE(log_has("made again"));
    TEST_ASSERT_TRUE(log_has("FX AUTOTUNE REC01.WAV resumed at"));
    TEST_ASSERT_EQUAL_UINT32(1U, s_first_flags);
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE);
}

void test_the_percent_never_drops_across_parks_and_resumes(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_AUTOTUNE, s_now));
    uint8_t last_want = 0U;
    uint8_t last_bg = 0U;
    uint32_t parks = 0U;
    fxj_step_t r = FXJ_NOTHING;
    for (uint32_t i = 1U; i < MAX_STEPS && !is_end(r); i++)
    {
        if ((i % 17U) == 0U)
        {
            (void)park_now();
            parks++;
            TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_AUTOTUNE, s_now));
        }
        fxj_status_t st;
        fxj_status(&s_j, false, s_now, &st);
        TEST_ASSERT_TRUE(fxj_want_percent(&s_j) >= last_want);  /* the Preparing screen and footer */
        TEST_ASSERT_TRUE(st.job_pct >= last_bg);                /* the debug page's job row */
        last_want = fxj_want_percent(&s_j);
        last_bg = st.job_pct;
        r = step_in_budget(false);
    }
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, r);
    TEST_ASSERT_TRUE(parks >= 4U);
    TEST_ASSERT_TRUE(log_has("parked at"));
    TEST_ASSERT_TRUE(log_has("resumed at"));
    TEST_ASSERT_FALSE(log_has("made again"));
    TEST_ASSERT_EQUAL_UINT32(1U, s_first_flags);
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE);
}

