/* The first log line that has text, or "" if none has. */
static const char *first_log_with(const char *text)
{
    for (uint32_t i = 0U; i < s_log_count && i < LOG_LINES; i++)
    {
        if (strstr(s_log[i], text) != NULL)
        {
            return s_log[i];
        }
    }
    return "";
}

/* Autotune (the dearest effect, made last by the queue's cheapest-first
 * order) is half made in the background. PLAY of the original touches the
 * recording and selects no effect, and parks the job. After STOP the
 * background carries Autotune on FIRST, exactly, before the cheaper effects
 * the touch queued: one of their FIRST chunks would replace its effect state
 * in FxRenderTask, and it would then need a rebuild (a pre-roll). */
void test_the_background_carries_on_an_exact_parked_pair_before_cheaper_effects(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    fxj_select(&s_j, FXS_EFFECT_AUTOTUNE);                      /* recorded with Autotune picked */
    fxj_touch(&s_j, "REC01.WAV");
    for (uint32_t i = 0U; i < MAX_STEPS && !(s_j.job.active && s_j.job.pipe.src_done >= 16384U); i++)
    {
        (void)step_in_budget(true);
    }
    TEST_ASSERT_EQUAL_UINT8(FXS_EFFECT_AUTOTUNE, s_j.job.effect);
    fxj_touch(&s_j, "REC01.WAV");                               /* PLAY with no effect ... */
    fxj_select(&s_j, FXS_EFFECT_NONE);
    (void)park_now();                                           /* ... parks it */
    TEST_ASSERT_TRUE(log_has("FX AUTOTUNE REC01.WAV parked at"));

    TEST_ASSERT_EQUAL(FXJ_NOTHING, run(true));                  /* STOP: the background goes on */
    TEST_ASSERT_TRUE(log_has("FX AUTOTUNE REC01.WAV resumed at"));
    TEST_ASSERT_FALSE(log_has("made again"));
    TEST_ASSERT_EQUAL_STRING_LEN("FX AUTOTUNE REC01.WAV made in", first_log_with(" made in "), 29U);
    TEST_ASSERT_EQUAL_UINT32(FXS_EFFECT_COUNT, s_first_flags);  /* Autotune's FIRST was not repeated */
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE);
}

/* A disk error on J_CLEAN's Stat of the kept .TMP says nothing about the
 * file: the job fails as a card READ (not "its .TMP changed", not a card
 * write), keeps its row and its .TMP, and once the card reads again the
 * pair carries on exactly. */
void test_a_disk_error_on_the_kept_tmp_keeps_its_row_and_the_retry_carries_on(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_PITCHUP, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_PITCHUP, 16384U);
    const uint8_t pct = park_now();
    char tmp[FXS_PATH_LEN];
    fx_path(FXS_EFFECT_PITCHUP, "REC01.WAV", true, tmp);

    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_PITCHUP, s_now));
    step_until_phase(J_CLEAN);
    StoragePortFake_CardFailOp(STORAGE_FAKE_OP_STAT, 0U, STORAGE_READ_FAIL);
    TEST_ASSERT_EQUAL(FXJ_WANT_FAILED, run_waited());
    TEST_ASSERT_EQUAL(FXJ_FAIL_CARD_READ, fxj_last_fail(&s_j));
    TEST_ASSERT_FALSE(log_has("its .TMP changed"));
    TEST_ASSERT_NOT_NULL(row_of("REC01.WAV", FXS_EFFECT_PITCHUP));
    TEST_ASSERT_TRUE(StoragePortFake_CardExists(tmp));

    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_PITCHUP, s_now));
    TEST_ASSERT_EQUAL_UINT8(pct, fxj_want_percent(&s_j));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_TRUE(log_has("resumed at"));
    TEST_ASSERT_EQUAL_UINT32(1U, s_first_flags);
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_PITCHUP);
}

/* The proof that the byte-for-byte checks of this group mean something:
 * the fake effect's memory catches a wrong FxRenderTask state. Each fault
 * below is FORCED into a resume the engine then takes for exact, and each
 * one changes the file's bytes. (A fake whose state is the same at every
 * chunk edge would miss all three.) */
typedef enum {
    FAULT_FIRST_AGAIN = 0,   /* the resumed job sends a second FIRST: FxRenderTask starts over */
    FAULT_CHUNK_LOST,        /* the park gave up a chunk FxRenderTask had made: it is made twice */
    FAULT_OTHER_JOB_RAN,     /* another job's chunks went through FxRenderTask in between */
    FAULT_COUNT
} state_fault_t;

static void resume_with_a_forced_state_fault(state_fault_t fault)
{
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, 16384U);
    if (fault == FAULT_CHUNK_LOST)
    {
        s_mode = RENDER_HOLDS;
        step_until_action(FXP_WAIT, false);         /* a chunk is out: FxRenderTask has made it */
        fxj_park(&s_j);                             /* the wait ran out: the park gives it up */
        answer();                                   /* its late reply is dropped */
        s_mode = RENDER_ANSWERS;
        s_j.dsp_ok = true;                          /* FORCED: as if nothing was lost */
    }
    else
    {
        (void)park_now();
    }
    if (fault == FAULT_OTHER_JOB_RAN)
    {
        make_file("REC02.WAV", FXS_EFFECT_ROBOT);
        s_j.dsp_job = row_of("REC01.WAV", FXS_EFFECT_ECHO)->resume.id;   /* FORCED: as if REC01's state */
    }
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
    if (fault == FAULT_FIRST_AGAIN)
    {
        step_until_phase(J_RUN);
        s_j.job.pipe.first_sent = false;            /* FORCED: its next chunk carries FIRST */
    }
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_TRUE_MESSAGE(log_has("FX ECHO REC01.WAV resumed at"), s_case);   /* taken for exact */
    char path[FXS_PATH_LEN];
    fx_path(FXS_EFFECT_ECHO, "REC01.WAV", false, path);
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(s_ref_size[0], StoragePortFake_CardFileSize(path), s_case);
    TEST_ASSERT_TRUE_MESSAGE(memcmp(s_ref[0], StoragePortFake_CardFileData(path), s_ref_size[0]) != 0, s_case);
}

void test_the_fake_effect_memory_sees_a_wrong_effect_state(void)
{
    for (uint32_t fault = 0U; fault < (uint32_t)FAULT_COUNT; fault++)
    {
        (void)snprintf(s_case, sizeof(s_case), "state fault %lu", (unsigned long)fault);
        make_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO, RATE_32K, 1U);    /* leaves a fresh engine */
        resume_with_a_forced_state_fault((state_fault_t)fault);
    }
}

