    uint8_t *shorter = (uint8_t *)malloc(size);
    TEST_ASSERT_NOT_NULL(shorter);
    memcpy(shorter, StoragePortFake_CardFileData("FX/ROBOT/REC01.TMP"), size);
    TEST_ASSERT_TRUE(StoragePortFake_CardAddFile("FX/ROBOT/REC01.TMP", shorter, size));
    free(shorter);
