void test_a_new_job_number_is_never_0_the_dsp_job_or_a_parked_jobs(void)
{
    add_recording("REC01.WAV", 1U);
    add_recording("REC02.WAV", 2U);
    add_recording("REC03.WAV", 3U);
    s_j.next_id = FXJ_NO_JOB;                                   /* the counter has wrapped */
    want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, PARTLY_SAMPLES);
    TEST_ASSERT_TRUE(s_j.job.id != FXJ_NO_JOB);
    TEST_ASSERT_EQUAL_UINT16(s_j.job.id, s_j.dsp_job);

    s_j.next_id = s_j.dsp_job;                                  /* FxRenderTask holds REC01's state */
    want_and_run_partly("REC02.WAV", FXS_EFFECT_ECHO, 0U);
    const uint16_t rec01 = row_of("REC01.WAV", FXS_EFFECT_ECHO)->resume.id;
    TEST_ASSERT_TRUE(s_j.job.id != rec01);

    s_j.next_id = rec01;                                        /* REC01 is parked under that number */
    s_j.dsp_job = FXJ_NO_JOB;
    want_and_run_partly("REC03.WAV", FXS_EFFECT_ECHO, 0U);
    TEST_ASSERT_TRUE(s_j.job.id != rec01);
}

void test_the_fake_card_opens_an_existing_fx_file_and_never_seeks_past_its_end(void)
{
    uint8_t data[100];
    memset(data, 0x11, sizeof(data));
    uint32_t size = 7U;
    TEST_ASSERT_TRUE(StoragePortFake_CardAddDir("FX"));
    TEST_ASSERT_TRUE(StoragePortFake_CardAddDir("FX/ECHO"));
    TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND, Storage_FxOpenExisting("FX/ECHO/A.TMP", &size));
    TEST_ASSERT_FALSE(StoragePortFake_CardExists("FX/ECHO/A.TMP"));        /* never created */
    TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND, Storage_FxOpenExisting("FX/ECHO", &size));

    TEST_ASSERT_TRUE(StoragePortFake_CardAddFile("FX/ECHO/A.TMP", data, sizeof(data)));
    TEST_ASSERT_EQUAL(STORAGE_OK, Storage_FxOpenExisting("FX/ECHO/A.TMP", &size));
    TEST_ASSERT_EQUAL_UINT32(sizeof(data), size);
    TEST_ASSERT_EQUAL_UINT32(1U, StoragePortFake_CardSlotsInUse());
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, Storage_FxSeek(101U));          /* past the end */
    TEST_ASSERT_EQUAL(STORAGE_OK, Storage_FxSeek(100U));                   /* the end itself */
    TEST_ASSERT_EQUAL(STORAGE_OK, Storage_FxWrite(data, 4U));
    TEST_ASSERT_EQUAL(STORAGE_OK, Storage_FxClose());
    TEST_ASSERT_EQUAL_UINT32(104U, StoragePortFake_CardFileSize("FX/ECHO/A.TMP"));
    TEST_ASSERT_EQUAL_UINT32(0U, StoragePortFake_CardSlotsInUse());

    StoragePortFake_CardSetReadOnly("FX/ECHO/A.TMP", true);
    TEST_ASSERT_EQUAL(STORAGE_REFUSED, Storage_FxOpenExisting("FX/ECHO/A.TMP", &size));
    StoragePortFake_CardPull(true);
    TEST_ASSERT_EQUAL(STORAGE_READ_FAIL, Storage_FxOpenExisting("FX/ECHO/A.TMP", &size));
}

/* ======================================================================= */
/* 10. The rebuild (TEAM CODE, written by Brendon, 30 Oct 2026)             */
/* ======================================================================= */
/* REC01 is parked, then another job (REC02) is made, so FxRenderTask's state
 * is REC02's. When REC01 is wanted again it is REBUILT: the effect starts at
 * S a little before the resume point R, the output of [S, R) is thrown away,
 * and the chunk at R brings REC01's carry (RESTORE). The fake effect's carry
 * is its hash, its short memory the chunk before's last input, so only a
 * rebuild that does all of this right makes the reference file. */

#define LONG_SOURCE_S   6U      /* long enough that Echo's and Reverb's 4 s pre-roll can start after 0 */

/* The rule the rebuild must follow, written from the spec (Tom's
 * fx_render.h), not from fx_job.c's constants: S is on a 64 ms grid of
 * 48 kHz output samples, at least 64 ms (Echo, Reverb: 4 s) before R, or 0
 * if there is no such point. In source samples; R is a chunk edge. */
static uint32_t expected_preroll_start(uint8_t effect, uint32_t rate, uint32_t at)
{
    const uint32_t out_per_ms = 48U;
    const bool long_memory = (effect == FXS_EFFECT_ECHO) || (effect == FXS_EFFECT_REVERB);
    const uint32_t preroll_out = (long_memory ? 4000U : 64U) * out_per_ms;
    const uint32_t grid_out = 64U * out_per_ms;
    const uint32_t at_out = (rate == RATE_48K) ? at : (at / 2U) * 3U;
    if (at_out <= preroll_out)
    {
        return 0U;
    }
    const uint32_t start_out = ((at_out - preroll_out) / grid_out) * grid_out;
    return (rate == RATE_48K) ? start_out : (start_out / 3U) * 2U;
}

/* REC01 (effect) is being made; want REC02 (another effect) and make it,
 * so REC01 is parked and FxRenderTask's state becomes REC02's. Returns a
 * copy of REC01's park row. */
static fxj_parked_t park_by_another_job(uint8_t effect)
{
    const uint8_t other = (uint8_t)((effect % FXS_EFFECT_COUNT) + 1U);
    answer();                                       /* the glue's wait before the park */
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC02.WAV", other, s_now));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    const fxj_parked_t *row = row_of("REC01.WAV", effect);
    TEST_ASSERT_NOT_NULL_MESSAGE(row, s_case);
    return *row;
}

/* Want REC01 again and run it to the end, checking at every step that the
 * percentage shown never drops and that nothing is written or staged while
 * the pre-roll runs (until the reply of the chunk at R). */
static void run_the_rebuild(uint8_t effect, uint32_t at, uint8_t parked_pct)
{
    const uint32_t writes = StoragePortFake_GetOpCallCount(STORAGE_FAKE_OP_FX_WRITE);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", effect, s_now));
    uint8_t last = fxj_want_percent(&s_j);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(parked_pct - (parked_pct % FXJ_PCT_STEP_WAIT), last, s_case);   /* at once */
    fxj_step_t r = FXJ_NOTHING;
    for (uint32_t i = 0U; i < MAX_STEPS && !is_end(r); i++)
    {
        r = step_in_budget(false);
        if (!s_j.job.active)
        {
            continue;
        }
        TEST_ASSERT_TRUE_MESSAGE(fxj_want_percent(&s_j) >= last, s_case);     /* never down */
        last = fxj_want_percent(&s_j);
        if (s_j.job.phase == J_RUN && s_j.job.pipe.src_done <= at)
        {
            TEST_ASSERT_EQUAL_UINT32_MESSAGE(writes, StoragePortFake_GetOpCallCount(STORAGE_FAKE_OP_FX_WRITE), s_case);
            TEST_ASSERT_EQUAL_UINT32_MESSAGE(0U, s_j.job.pipe.out_staged, s_case);
        }
    }
    TEST_ASSERT_EQUAL_MESSAGE(FXJ_WANT_DONE, r, s_case);
}

/* One rebuild case: REC01 (LONG_SOURCE_S at rate) parked once at least
 * `parked_at` source samples are done, REC02 made, REC01 wanted again. */
static void rebuild_and_check(uint8_t effect, uint32_t rate, uint32_t parked_at)
{
    fresh_with_memory();
    add_source_s("REC01.WAV", rate, 1U, LONG_SOURCE_S);
    add_source("REC02.WAV", rate, 2U);
    want_and_run_partly("REC01.WAV", effect, parked_at);
    const fxj_parked_t row = park_by_another_job(effect);
    const uint32_t at = row.resume.src_at;
    const uint32_t from = expected_preroll_start(effect, rate, at);
    const uint32_t total = LONG_SOURCE_S * rate;
    const uint32_t firsts = s_first_flags;
    s_restores = 0U;

    run_the_rebuild(effect, at, row.resume.pct);
    expect_reference(0U, "REC01.WAV", effect);                                  /* the one-go file */
    TEST_ASSERT_TRUE_MESSAGE(log_has("rebuilt, pre-roll"), s_case);
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(firsts + 1U, s_first_flags, s_case);
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(from, s_first_at, s_case);                 /* FIRST at S */
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(total - from, s_sent_since_first, s_case); /* [S, end) sent once: <= a restart */
    if (from > 0U)
    {
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(1U, s_restores, s_case);
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(at, s_restore_at, s_case);             /* RESTORE at R ... */
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(at - from, s_preroll_sent, s_case);    /* ... after exactly [S, R) */
        TEST_ASSERT_EQUAL_MEMORY_MESSAGE(row.resume.carry, s_restore_carry, FXJ_CARRY_BYTES, s_case);
    }
    else
    {
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(0U, s_restores, s_case);              /* from 0: no RESTORE */
    }
}

/* Every effect, both rates, two resume points: about 25 % (Echo and
 * Reverb then rebuild from 0, the others from 64-128 ms before R) and about
 * 80 % (all from S > 0: 4 s before R for Echo and Reverb). */
void test_a_rebuilt_file_is_byte_identical_for_every_effect_rate_and_resume_point(void)
{
    static const uint32_t rates[] = { RATE_32K, RATE_48K };
    static const uint32_t percents[] = { 25U, 80U };
    for (uint8_t effect = FXS_EFFECT_AUTOTUNE; effect <= FXS_EFFECT_COUNT; effect++)
    {
        for (size_t r = 0U; r < (sizeof(rates) / sizeof(rates[0])); r++)
        {
            make_reference_s(0U, "REC01.WAV", effect, rates[r], 1U, LONG_SOURCE_S);
            for (size_t p = 0U; p < (sizeof(percents) / sizeof(percents[0])); p++)
            {
                (void)snprintf(s_case, sizeof(s_case), "effect %u, %lu Hz, parked at %lu %%",
                               (unsigned)effect, (unsigned long)rates[r], (unsigned long)percents[p]);
                rebuild_and_check(effect, rates[r], (LONG_SOURCE_S * rates[r] * percents[p]) / 100U);
            }
        }
    }
}

/* Close to the start, S is 0 for every effect: the rebuild runs the effect
 * from the first sample (FIRST at 0, its state at R is the one-go state
 * already), so no RESTORE is sent. */
void test_a_rebuild_near_the_start_runs_from_0_with_no_restore(void)
{
    (void)snprintf(s_case, sizeof(s_case), "near the start");
    make_reference_s(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE, RATE_32K, 1U, LONG_SOURCE_S);
    rebuild_and_check(FXS_EFFECT_AUTOTUNE, RATE_32K, 2048U);        /* R about 2560: 80 ms of output */
    TEST_ASSERT_EQUAL_UINT32(0U, s_first_at);
    TEST_ASSERT_EQUAL_UINT32(0U, s_restores);
}

/* Where a park cuts a rebuild short. */
typedef enum {
    CUT_AFTER_ONE_CHUNK = 0,      /* a pre-roll chunk is back, the pre-roll not done */
    CUT_BEFORE_RESTORE,           /* the whole pre-roll is back, the RESTORE chunk not yet sent */
    CUT_COUNT
} preroll_cut_t;

static bool preroll_cut_reached(preroll_cut_t cut, uint32_t from, uint32_t at)
{
    const fx_pipe_t *p = &s_j.job.pipe;
    if (!s_j.job.active || s_j.job.phase != J_RUN || p->inflight)
    {
        return false;
    }
    if (cut == CUT_AFTER_ONE_CHUNK)
    {
        return p->src_done > from && p->src_done < at;
    }
    return p->src_done == at && p->src_sent == at;
}

/* A park in the middle of a pre-roll: FxRenderTask then holds a half-rebuilt
 * state that is NOT the one-go state (dsp_ok is false), so the next resume
 * must rebuild again, even with no other job in between. Its row keeps the
 * resume point R, the percentage and the carry of R. (Before critic 2's fix
 * the engine took such a park for exact, and the file came out wrong.) */
void test_a_park_during_a_preroll_is_rebuilt_again_never_taken_for_exact(void)
{
    for (uint32_t cut = 0U; cut < (uint32_t)CUT_COUNT; cut++)
    {
        (void)snprintf(s_case, sizeof(s_case), "cut %lu", (unsigned long)cut);
        make_reference_s(0U, "REC01.WAV", FXS_EFFECT_ECHO, RATE_32K, 1U, LONG_SOURCE_S);
        add_source_s("REC01.WAV", RATE_32K, 1U, LONG_SOURCE_S);
        add_source("REC02.WAV", RATE_32K, 2U);
        want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, (LONG_SOURCE_S * RATE_32K * 4U) / 5U);
        const fxj_parked_t row = park_by_another_job(FXS_EFFECT_ECHO);
        const uint32_t at = row.resume.src_at;
        const uint32_t from = expected_preroll_start(FXS_EFFECT_ECHO, RATE_32K, at);
        TEST_ASSERT_TRUE(from > 0U);

        TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
        for (uint32_t i = 0U; i < MAX_STEPS; i++)
        {
            answer();                                   /* FxRenderTask's reply first, then the check */
            if (preroll_cut_reached((preroll_cut_t)cut, from, at))
            {
                break;
            }
            (void)fxj_step(&s_j, false, s_now);
            s_now++;
        }
        TEST_ASSERT_TRUE_MESSAGE(preroll_cut_reached((preroll_cut_t)cut, from, at), s_case);
        TEST_ASSERT_FALSE_MESSAGE(s_j.dsp_ok, s_case);                  /* not the one-go state */
        const uint8_t pct = park_now();                                 /* PLAY, say */
        const fxj_parked_t *again = row_of("REC01.WAV", FXS_EFFECT_ECHO);
        TEST_ASSERT_NOT_NULL_MESSAGE(again, s_case);
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(at, again->resume.src_at, s_case);
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(row.resume.out_at, again->resume.out_at, s_case);
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(row.resume.pct, again->resume.pct, s_case);
        TEST_ASSERT_EQUAL_MEMORY_MESSAGE(row.resume.carry, again->resume.carry, FXJ_CARRY_BYTES, s_case);
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(row.resume.pct - (row.resume.pct % FXJ_PCT_STEP_WAIT), pct, s_case);

        /* Wanted again at once (no other job ran): rebuilt again, exactly right. */
        const uint32_t firsts = s_first_flags;
        s_log_count = 0U;
        TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
        TEST_ASSERT_EQUAL_MESSAGE(FXJ_WANT_DONE, run_waited(), s_case);
        TEST_ASSERT_TRUE_MESSAGE(log_has("rebuilt, pre-roll"), s_case);
        TEST_ASSERT_TRUE_MESSAGE(log_has("its own state is not where it stopped"), s_case);
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(firsts + 1U, s_first_flags, s_case);
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(from, s_first_at, s_case);
        expect_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO);
    }
}

/* A rebuild from 0 (Echo on a 1 s recording) parked at once, before any
 * pre-roll chunk is back: nothing new is rendered yet, but the job still
 * holds its old progress, so its row keeps R and the percentage. */
void test_a_park_at_the_very_start_of_a_rebuild_keeps_the_row(void)
{
    (void)snprintf(s_case, sizeof(s_case), "park at the start");
    make_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_ECHO, 16384U);
    const fxj_parked_t row = park_by_another_job(FXS_EFFECT_ECHO);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
    step_until_action(FXP_SEND, false);             /* J_RUN: the first pre-roll chunk is read, none sent */
    TEST_ASSERT_EQUAL_UINT32(0U, s_j.job.pipe.src_done);
    (void)park_now();
    const fxj_parked_t *again = row_of("REC01.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_NOT_NULL(again);
    TEST_ASSERT_EQUAL_UINT32(row.resume.src_at, again->resume.src_at);
    TEST_ASSERT_EQUAL_UINT8(row.resume.pct, again->resume.pct);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_ECHO, s_now));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_ECHO);
}

/* After the RESTORE chunk's reply the state IS the one-go state again, so
 * a park from then on carries on exactly (no second FIRST). */
void test_a_park_after_the_restore_chunk_carries_on_exactly(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_AUTOTUNE, 16384U);
    const fxj_parked_t row = park_by_another_job(FXS_EFFECT_AUTOTUNE);
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_AUTOTUNE, s_now));
    for (uint32_t i = 0U; i < MAX_STEPS && !(s_j.job.phase == J_RUN && s_j.job.pipe.src_done > row.resume.src_at); i++)
    {
        (void)step_in_budget(false);
    }
    TEST_ASSERT_EQUAL_UINT32(1U, s_restores);
    TEST_ASSERT_TRUE(s_j.dsp_ok);
    (void)park_now();
    const uint32_t firsts = s_first_flags;
    s_log_count = 0U;
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_AUTOTUNE, s_now));
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    TEST_ASSERT_FALSE(log_has("rebuilt"));
    TEST_ASSERT_TRUE(log_has("resumed at"));
    TEST_ASSERT_EQUAL_UINT32(firsts, s_first_flags);
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE);
}

/* A carry FxRenderTask refuses (here: the row's carry wiped, as if no carry
 * had ever come back) stops the job with BAD_REQUEST: no file is made from
 * a wrong state, and the row goes. The next want makes the file from 0, and
 * it is right. */
void test_a_carry_fxrendertask_refuses_stops_the_job_and_the_next_try_starts_from_0(void)
{
    make_reference(0U, "REC01.WAV", FXS_EFFECT_PITCHUP, RATE_32K, 1U);
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_PITCHUP, 16384U);
    (void)park_by_another_job(FXS_EFFECT_PITCHUP);
    fxj_parked_t *row = (fxj_parked_t *)row_of("REC01.WAV", FXS_EFFECT_PITCHUP);
    memset(row->resume.carry, 0, FXJ_CARRY_BYTES);

    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_PITCHUP, s_now));
    TEST_ASSERT_EQUAL(FXJ_WANT_FAILED, run_waited());
    TEST_ASSERT_EQUAL(FXJ_FAIL_BAD_REQUEST, fxj_last_fail(&s_j));
    TEST_ASSERT_EQUAL_UINT32(1U, s_restores);
    TEST_ASSERT_NULL(row_of("REC01.WAV", FXS_EFFECT_PITCHUP));
    TEST_ASSERT_FALSE(StoragePortFake_CardExists("FX/PITCHUP/REC01.WAV"));
    TEST_ASSERT_FALSE(s_j.dsp_ok);
    expect_no_file_open();

    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_PITCHUP, s_now));
    TEST_ASSERT_FALSE(s_j.job.resume.valid);
    TEST_ASSERT_EQUAL(FXJ_WANT_DONE, run_waited());
    expect_reference(0U, "REC01.WAV", FXS_EFFECT_PITCHUP);
}

/* The proof that group 10's byte checks mean something: each mistake below
 * is FORCED into a rebuild, and each one changes the file. */
typedef enum {
    REBUILD_NO_RESTORE = 0,       /* the chunk at R goes without RESTORE: the carry is not loaded */
    REBUILD_WRONG_CARRY,          /* RESTORE with another point's carry */
    REBUILD_NO_PREROLL,           /* the effect starts at R itself: the short memory is empty */
    REBUILD_PREROLL_KEPT,         /* the pre-roll's output is written into the file too */
    REBUILD_FAULT_COUNT
} rebuild_fault_t;

static void rebuild_with_a_forced_fault(rebuild_fault_t fault)
{
    add_source("REC01.WAV", RATE_32K, 1U);
    add_source("REC02.WAV", RATE_32K, 2U);
    want_and_run_partly("REC01.WAV", FXS_EFFECT_AUTOTUNE, 16384U);
    const fxj_parked_t row = park_by_another_job(FXS_EFFECT_AUTOTUNE);
    const uint32_t at = row.resume.src_at;
    if (fault == REBUILD_WRONG_CARRY)
    {
        fxj_parked_t *r = (fxj_parked_t *)row_of("REC01.WAV", FXS_EFFECT_AUTOTUNE);
        r->resume.carry[FAKE_CARRY_HASH] ^= 0x01U;               /* FORCED: a carry, but not R's */
    }
    TEST_ASSERT_EQUAL(FXJ_STARTED, fxj_want(&s_j, "REC01.WAV", FXS_EFFECT_AUTOTUNE, s_now));
    step_until_phase(J_SPACE);                                   /* J_OPEN_SRC planned the rebuild */
    fx_pipe_t *p = &s_j.job.pipe;
    TEST_ASSERT_TRUE_MESSAGE(p->src_read > 0U && p->src_read < at, s_case);
    if (fault == REBUILD_NO_RESTORE)
    {
        p->restore = false;                                      /* FORCED */
    }
    if (fault == REBUILD_NO_PREROLL)
    {
        fxp_rebuild(p, p->src_total, at, at, p->out_written);    /* FORCED: S = R */
        TEST_ASSERT_EQUAL(STORAGE_OK, Storage_Seek(s_j.job.src.data_offset + at * 2U));
    }
    if (fault == REBUILD_PREROLL_KEPT)
    {
        p->keep_from = p->src_read;                              /* FORCED: everything from S is kept */
    }
    TEST_ASSERT_EQUAL_MESSAGE(FXJ_WANT_DONE, run_waited(), s_case);
    TEST_ASSERT_TRUE_MESSAGE(log_has("rebuilt, pre-roll"), s_case);
    char path[FXS_PATH_LEN];
    fx_path(FXS_EFFECT_AUTOTUNE, "REC01.WAV", false, path);
    const bool same = (StoragePortFake_CardFileSize(path) == s_ref_size[0]) &&
                      (memcmp(s_ref[0], StoragePortFake_CardFileData(path), s_ref_size[0]) == 0);
    TEST_ASSERT_FALSE_MESSAGE(same, s_case);
}

void test_the_fake_effect_memory_sees_a_wrong_rebuild(void)
{
    for (uint32_t fault = 0U; fault < (uint32_t)REBUILD_FAULT_COUNT; fault++)
    {
        (void)snprintf(s_case, sizeof(s_case), "rebuild fault %lu", (unsigned long)fault);
        make_reference(0U, "REC01.WAV", FXS_EFFECT_AUTOTUNE, RATE_32K, 1U);    /* leaves a fresh engine */
        rebuild_with_a_forced_fault((rebuild_fault_t)fault);
    }
}

